#if FOO
public struct ArenaAllocatedPointer<Element: Sendable>: @ // c
unchecked Sendable {
  let pointer: UnsafePointer<Element>

  /// Create a pointer from an `UnsafePointer` that was allocated inside a
  /// ``RawSyntaxArena`` or ``SyntaxDataArena``.
  ///
  /// - Important: The client needs to ensure sure that the buffer is indeed
  ///   allocated by an arena and that the arena will outlive any users of this
  ///   ``ArenaAllocatedPointer``.
  init(_ pointer: UnsafePointer<Element>) {
    self.pointer = pointer
  }

  var pointee: Element {
    @_transparent unsafeAddress { pointer }
  }

  func advanced(by n: Int) -> Self {
    Self(pointer.advanced(by: n))
  }

  var unsafeRawPointer: UnsafeRawPointer {
    return UnsafeRawPointer(pointer)
  }
}
public struct LookaheadRanges: Sendable {
  /// For each node that is recorded for re-use, the number of UTF-8 bytes that the parser looked ahead to parse the node, measured from the start of the node’s leading trivia.
  ///
  /// This information can be used to determine whether a node can be reused in incremental parse. A node can only be re-used if no byte in its looked range has changed.
  var lookaheadRanges: [RawSyntax.ID: Int] = [:]

  public init() {}

  mutating func registerNodeForIncrementalParse(node: RawSyntax, lookaheadLength: Int) {
    self.lookaheadRanges[node.id] = lookaheadLength
  }
}
#endif

